import { Vibration, Button, View } from 'react-native';

const App = () => (
  <View>
    <Button title="Vibrate" onPress={() => Vibration.vibrate()} />
    <Button title="Vibrate Pattern (Android)" onPress={() => Vibration.vibrate([0, 500, 200, 500])} />
    <Button title="Stop Vibration" onPress={() => Vibration.cancel()} />
  </View>
);
